CREATE DATABASE IF NOT EXISTS french_riviera CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE french_riviera;
DROP TABLE IF EXISTS users; DROP TABLE IF EXISTS reservations; DROP TABLE IF EXISTS dishes; DROP TABLE IF EXISTS categories;
CREATE TABLE categories (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(60) NOT NULL, sort_order TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE dishes (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, category_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, short_description VARCHAR(255) NOT NULL, description TEXT NOT NULL, price DECIMAL(6,2) NOT NULL, image VARCHAR(255) NOT NULL, featured TINYINT(1) NOT NULL DEFAULT 0, FOREIGN KEY (category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE reservations (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL, email VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL, res_date DATE NOT NULL, res_time TIME NOT NULL, guests TINYINT UNSIGNED NOT NULL, notes VARCHAR(500) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_admin TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
