INSERT INTO categories (id,name,sort_order) VALUES (1,'Starters',1),(2,'Main Courses',2),(3,'Seafood',3),(4,'Desserts',4),(5,'Drinks',5);
INSERT INTO dishes (id,category_id,name,short_description,description,price,image,featured) VALUES
(1,1,'French Onion Soup','Slow-caramelised onions, rich beef broth, a gratinée crown of Gruyère.','A Parisian classic. Sweet yellow onions are caramelised for over an hour, deglazed with white wine and simmered in a deep beef and thyme broth. It is ladled into a stoneware crock, topped with a toasted baguette round and bubbling Gruyère, then gratinéed until golden.',9.50,'https://images.unsplash.com/photo-1547592180-85f173e0f1d5?auto=format&fit=crop&w=1200&q=85',0),
(2,1,'Escargots de Bourgogne','Six Burgundy snails baked in garlic, parsley and Normandy butter.','Tender Burgundy snails are baked in their shells with a fragrant butter of garlic, flat-leaf parsley, shallot and a touch of Pernod. Served sizzling with warm baguette for dipping.',13.00,'https://images.unsplash.com/photo-1476224203421-9ac39bcb3327?auto=format&fit=crop&w=1200&q=85',0),
(3,1,'Ratatouille Niçoise','Sun-ripened Provençal vegetables, olive oil and fresh basil.','Zucchini, aubergine, peppers and tomatoes slowly stewed in Provençal olive oil with thyme, garlic and basil, in the style of Nice. Served warm with a drizzle of aged balsamic and shaved Parmesan.',11.00,'https://images.unsplash.com/photo-1547592180-85f173e0f1d5?auto=format&fit=crop&w=1200&q=85',0),
(4,2,'Boeuf Bourguignon','Beef braised for hours in Burgundy red wine with lardons and pearl onions.','Beef chuck marinated overnight in Pinot Noir, then braised for four hours with smoked lardons, carrots, pearl onions and button mushrooms. Served over buttered pommes purée.',26.00,'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=1200&q=85',1),
(5,2,'Coq au Vin','Free-range chicken simmered in red wine, mushrooms and thyme.','Free-range chicken is browned in butter and simmered in red wine with lardons, mushrooms, baby onions and thyme until the sauce turns glossy and deep. A rustic dish from the French countryside.',24.00,'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1200&q=85',0),
(6,2,'Canard à l''Orange','Roasted duck breast with a bittersweet orange and Grand Marnier sauce.','Duck breast is roasted rosé, with crisp rendered skin, and glazed with a sauce of caramelised orange, duck jus and a splash of Grand Marnier. Served with fine green beans and orange segments.',29.00,'https://images.unsplash.com/photo-1518895949257-7621c3c786d7?auto=format&fit=crop&w=1200&q=85',0),
(7,2,'Steak Frites','Grilled entrecôte with béarnaise and hand-cut golden fries.','A 250 g entrecôte grilled to your preference and finished with house béarnaise, served with twice-fried hand-cut potatoes and a small salad with Dijon vinaigrette.',27.00,'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=1200&q=85',0),
(8,3,'Bouillabaisse Marseillaise','Traditional Provençal fish stew with saffron, fennel and rouille.','The signature fish stew of Marseille: rockfish, monkfish, red mullet and shellfish simmered with saffron, fennel, tomato and orange zest. Served with toasted croutons and garlicky rouille.',32.00,'https://images.unsplash.com/photo-1547592180-85f173e0f1d5?auto=format&fit=crop&w=1200&q=85',1),
(9,3,'Moules Marinières','Steamed mussels in white wine, shallots and cream, with fries.','Fresh mussels steamed open with shallots, white wine, parsley and a splash of cream. Served in a pot with crisp fries and fresh bread for the broth.',19.00,'https://images.unsplash.com/photo-1510130387422-82bed34b37e1?auto=format&fit=crop&w=1200&q=85',0),
(10,3,'Bar Grillé','Whole grilled sea bass with fennel, lemon and Provençal herbs.','Mediterranean sea bass grilled over fennel stalks with lemon, olive oil and herbes de Provence. Served with roasted fingerling potatoes and a light beurre blanc.',28.00,'https://images.unsplash.com/photo-1559847844-5315695dadae?auto=format&fit=crop&w=1200&q=85',0),
(11,4,'Crème Brûlée','Vanilla bean custard beneath a crackling caramelised sugar crust.','A silken custard of Madagascar vanilla, egg yolk and cream baked slowly, chilled overnight, and finished with a torched crust of caramelised sugar.',9.00,'https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=1200&q=85',1),
(12,4,'Tarte Tatin','Upside-down caramelised apple tart with crème fraîche.','Apples cooked in butter and caramel beneath a layer of buttery puff pastry, baked and inverted while warm. Served with a spoonful of crème fraîche.',10.00,'https://images.unsplash.com/photo-1565958011703-44f9829ba187?auto=format&fit=crop&w=1200&q=85',0),
(13,4,'Chocolat Soufflé','Warm dark chocolate soufflé, baked to order, with crème anglaise.','Made to order with 70% Valrhona chocolate and whipped egg whites, baked until it rises tall and airy. Our server pours warm crème anglaise into the centre at the table. Please allow 20 minutes.',12.00,'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=1200&q=85',0),
(14,4,'Macarons Assortis','Five delicate macarons in seasonal flavours.','Five almond macarons filled with ganache, fruit curd or buttercream. Flavours include pistachio, raspberry, salted caramel, lavender and dark chocolate.',8.50,'https://images.unsplash.com/photo-1559737558-2f5a35f4523?auto=format&fit=crop&w=1200&q=85',0),
(15,5,'Vins de France','Curated French wines by the glass, from Provence rosé to Bordeaux.','A rotating selection of regional French wines by the glass: Provence rosé, Chablis, Sancerre, Côtes du Rhône and Bordeaux. Our sommelier will gladly recommend a pairing. Price shown per glass; bottles from €32.',8.00,'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=1200&q=85',0),
(16,5,'Espresso','Rich, aromatic espresso served with a small dark chocolate.','A classic espresso from a medium-dark roast, with a thick golden crema. Served with a square of dark chocolate. Decaffeinated is available.',3.50,'https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=1200&q=85',0),
(17,5,'Jus Frais Pressés','Freshly squeezed orange, grapefruit or apple juice.','Squeezed to order from Mediterranean oranges, pink grapefruit or crisp Normandy apples. Served chilled with a sprig of mint.',6.00,'https://images.unsplash.com/photo-1547592180-85f173e0f1d5?auto=format&fit=crop&w=1200&q=85',0),
(18,5,'Limonade Maison','House lemonade with Menton lemons, mint and sparkling water.','Our non-alcoholic signature: Menton lemons, fresh mint and a touch of honey topped with sparkling water. Elderflower and lavender variations are also available.',5.50,'https://images.unsplash.com/photo-1476224203421-9ac39bcb3327?auto=format&fit=crop&w=1200&q=85',0);
